function UILoadingPanel:Awake()
    self.LoadingValueText = KTool.GetComponent(self.LoadingValueText.gameObject, typeof(TextMeshProUGUI))
    self.slider = KTool.GetComponent(self.LoadingValueText.transform.parent.parent.gameObject, typeof(Slider))
    KTool.SetActive(self.controller.gameObject, true)
    -----判断如果进战斗关闭背景音乐
    local moviePath = KCookie.Get(Constants.UICacheDataKeys.SPECIFY_SCENE_LOADING_MOVIE_PATH)
    if self.args then
        moviePath = self.args.moviePath
    end
    if string.isEmpty(moviePath) or self:IsDisableMovie() then
        self._isShowProgress = true
        if not isNull(self.Movie) then
            KTool.SetActive(self.Movie.gameObject, false)
        end

        local path = UICommonUtils.GetLoadingPicUrl(true)
        ---@type UnityEngine.UI.RawImage  -- 修改背景墙
        local rawImage = KTool.GetComponent(self.ImgBg.gameObject, typeof(CS.UnityEngine.UI.RawImage))
        if rawImage then
            local textureLoader = TextureLoader.Load(path, nil, CS.Engine.Modules.LoaderMode.Sync, true)
            if textureLoader.IsSuccess then
                textureLoader:Retain(rawImage)
                rawImage.texture = textureLoader.Asset
            end
            textureLoader:Release()
        end
    else
        KCookie.Set(Constants.UICacheDataKeys.SPECIFY_SCENE_LOADING_MOVIE_PATH)
        --- clear cookie
        self:HideLoadingBg()
        -- KTool.SetActive(self.Movie.gameObject, true)
        -- KTool.SetActive(self.ImgBg.gameObject, false)
        self.Movie.player:SetFile(nil, GameUtils.GetManaPath(moviePath))
        self.Movie.player:Prepare()
    end
end

function UILoadingPanel:HideLoadingBg()
    KTool.SetActive(self.LoadingBg.gameObject, false)
end

function UILoadingPanel:Start()
    if not QuestConfMgr:GetInstance():IsPassQuest(Constants.QUEST_GUIDE_ID) then
        ---第一次建角色的记录统计
        xRecord.record('1-006')
    end

    KTool.SetActive(self.Tips.gameObject, false)
    self.eventsDecorated_ = CfUtils.EventsDecorated({
        [Constants.EventNames.LoadingResourceError] = Bind(self, self.OnLoadingResourceErrorHandler_),
    })

    if not isNull(UIModule.RootCanvas.transform:Find("UINavigationBarRoot")) then
        GameUtils.HideBlack(0.3)   -- 序章1剧情结束之后，要请求服务器，等服务器返回以后才进入下一关。所以序章2进入loading的时候要HideBlack
    end

    if Config.REVIEW then
        self.LoadingTypeText.text = localize("加载中")
    end

    if self._isShowProgress then
        self:__Progress(0)
        if checkInt(self.loadingType) == Constants.LoadingType.Battle then
            local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
            if behaviourAction then
                behaviourAction.UpdateAction = function(behaviourAction)
                    self:Update()
                end
            end
        end
    end

    
    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end

    --世界boss内转场会使用这个界面没参数

    if not isNull(self.args) then
        self.co = cs_coroutine.start(function()
            CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.High
            UINavigationBarRoot.Instance:SetActive(false)
            

            local parameters            = self.args.parameters
            local isBackToHomeScene     = false
            local isReleaseBattle       = false
            local extraUIPages          = nil
            local isMergeExtraUIPage    = nil
            if parameters then
                isBackToHomeScene     = parameters.isBackToHomeScene == true
                isReleaseBattle       = parameters.isReleaseBattle == true
                extraUIPages          = parameters.extraUIPages
                isMergeExtraUIPage    = parameters.isMergeExtraUIPage == true
            end

            if isBackToHomeScene then
                UIModule.Clear()
            else
                Events.Broadcast(Constants.EventNames.FightPreHandle)
                ---去战斗的情况
                UIModule.StoreStackState(self.args)
            end

            local isSaveSceneRecord = self.args.parameters ~= nil and self.args.parameters.isSaveSceneRecord
            ---关闭所有的窗口
            xTry(function()
                local needWaitDialogClose = false
                local coWait = CoWait.Start()
                for i, v in support.list_ipairs(UIModule.CurrentScreen.dialogs) do
                    local isRemove = string.isEmpty(v.Argument.extra)
                    local coClose = UIModule.CloseDialog(v, isRemove and not isSaveSceneRecord)
                    if not isNull(coClose) then
                        needWaitDialogClose = true
                        coWait:Coroutine(coClose)
                    end
                end
                UIModule.CurrentScreen.dialogs:Clear()
                while needWaitDialogClose and not coWait.IsFinish do
                    coroutine.yield()
                end     
            end)

            if isBackToHomeScene then
                --- 只保存 self.args.id中的UIPage 
                local uiPages = UIModule.Instance.uiPages
                local count   = uiPages.Count
                if count > 0 then
                    local screenId = self.args.id
                    for i = count - 1, 0, -1 do
                        local uiPage = uiPages[i]
                        if uiPage.screenId ~= screenId then
                            uiPages:RemoveAt(i)
                        end
                    end
                end
                
                --- 修正scendId
                local argument = clone(checkTable(self.args))
                UIModule.CurrentScreen.Argument = argument
                
                --- 填充额外的 UI Page
                if extraUIPages then
                    local AddUIPages = function ()
                        for i, v in ipairs(extraUIPages) do
                            UIModule.AddUIPage(v)
                        end
                    end

                    if isMergeExtraUIPage then
                        --- 将附加的ui page 合并到要去的场景第一个ui history中
                        count = uiPages.Count
                        if count > 0 then
                            local uiPage = uiPages[count - 1]
                            local uiArguments = uiPage.uiArguments
                            for i, arg in ipairs(extraUIPages) do
                                local vo = UIModule.GetPrefabVoByRefId(arg.id)
                                arg.path = vo:Get("path")
                                arg.status = vo:Get("status")
                                arg.hasExcluded = true
                                uiArguments:Add(arg)
                            end

                        else
                            AddUIPages()
                        end
                        
                    else
                        AddUIPages()
                    end
                    parameters.extraUIPages = nil
                end
            end

            ---开始加载战斗场景
            xpcall(function()
                KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
                if self.loadingType ~= Constants.LoadingType.Battle then
                    if self.args then
                        if self.args.parameters and self.args.parameters.isReleaseBattle then
                            FightPreWarMgr:GetInstance():ClearBattleBuff()
                            if BattleViewMgr then
                                BattleViewMgr:SetCameraVMActive(false)
                                BattleViewMgr:ResetOutsetBattleSettings()
                            end
                            if BattleEndMgr then
                                --- 结算表演的timeline会改镜头焦距，需要在打开主场景之前先重置掉才行
                                BattleEndMgr:ResetCameraAndLight()
                            end
                            if BattleViewMgr then
                                BattleViewMgr:OnDestroy()
                                BattleViewMgr = nil
                            end
                            CS.UnityEngine.LightmapSettings.lightProbes = nil
                        end
                        cs_coroutine.yield_return(UIModule.OpenScreen(self.args, true, self.dialogArgs))
                        ---@type XMainHome
                        local env = UIModule.CurrentScreen.Env
                        env:SetLoadingUI(self)
                        cs_coroutine.yield_return(env:AsyncLoadingResources())
                    end
                else
                    if self.args then
                        if self.args.parameters and self.args.parameters.questId then
                            local levelType = GoodsUtils.GetIdType(self.args.parameters.questId, Constants.IDArea.Quests)     --关卡类型
                            if levelType == Constants.IDType.QuestChapterEvent then
                                CS.Engine.UI.UIModule.ResetStack()
                                cs_coroutine.yield_return(UIModule.OpenScreen(UIArgs(Constants.UITypeIds.UISceneHome), true, nil))
                                ---@type XMainHome
                                local env = UIModule.CurrentScreen.Env
                                cs_coroutine.yield_return(env:AsyncLoadingResources())
                                Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
                            end
                        end
                    end
                    BattleMgr = import('Game.Battle.Core.BattleMgr')
                    BattleViewMgr = import('Game.BattleView.Core.BattleViewMgr')
                    BattleViewMgr:Start()
                end

            end, function(err)
                print(err)
                printError(tostring(err))
            end)

        end)
    end
end

function UILoadingPanel:__Progress(value)
    --  local image = self.image
    --   if image then
    --     value = math.min(value, 100)
    --     image.fillAmount = checkNumber(value) * 0.01
    value = math.min(value, 1)
    if self._nowProgress and self._nowProgress > value then
        return
    end
    self._nowProgress = value
    local progress = math.floor(checkNumber(value * 100))
    local _string = string.format("%0.1f", progress)
    if self.slider then
        self.slider.value = value
    end
    self.LoadingValueText.text = _string .. "%"
end

function UILoadingPanel:Progress(value)
    value = value / 100
    self.targetValue = value
    local nowValue = self._nowProgress or 0

    if nowValue >= value then
        return
    end
    -- if value >= 1 then
    --     self.targetSpeed = (value - nowValue) / 0.01
    -- else
        self.targetSpeed = (value - nowValue) / 0.9--1秒到达
    -- end
end

function UILoadingPanel:Update()
    if self.targetValue then
        local value = self._nowProgress + (self.targetSpeed or 0.04) * CS.UnityEngine.Time.deltaTime
        self:__Progress(value)
        if self._nowProgress >= self.targetValue then
            self.targetValue = nil
        end
    else
        local value = self._nowProgress + 0.04 * CS.UnityEngine.Time.deltaTime
        self:__Progress(value)
    end
end

function UILoadingPanel:Close(immediate)
    UIModule.CurrentScreen.isLoadingFinished = true
    if not QuestConfMgr:GetInstance():IsPassQuest(Constants.QUEST_GUIDE_ID) then
        ---第一次建角色的记录统计
        xRecord.record('1-007')
    end
    if self.isShowMovie then
        self:Stop()
    end
    local behaviourAction = KTool.GetComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = nil
    end
    if not isNull(self.co) then
        cs_coroutine.stop(self.co)
        self.co = nil
    end
    if self.loadingType ~= Constants.LoadingType.MainHome then
        CS.UnityEngine.Application.backgroundLoadingPriority = CS.UnityEngine.ThreadPriority.BelowNormal
    end
    if not isNull(self.ActiveNode) then
        KTool.SetActive(self.ActiveNode.gameObject, true)
    end

    if immediate then
        GameObject.Destroy(self.controller.gameObject)
    else
        ---TODO 默认延时1秒才关闭，这样会增加加载时长，避免这样使用
        GameObject.Destroy(self.controller.gameObject, 1)
    end
end

function UILoadingPanel:Stop()
    self.Movie.player.statusChangeCallback = nil
    self.Movie:Stop()
end

function UILoadingPanel:Play(playEndCallback)
    if self:IsDisableMovie() or isNull(self.Movie) then
        self._loopTimes = 1
        return
    end
    self.isShowMovie = true
    -- KTool.SetActive(self.Movie.gameObject, true)
    -- self.Movie.player:SetFile(nil, GameUtils.GetManaPath(moviePath))
    self.Movie.player.statusChangeCallback = function(playerStatus)
        if playerStatus == PlayEnd then
            if playEndCallback then
                if playEndCallback() then
                    self.Movie:Play()
                end
            end
            self._loopTimes = self._loopTimes + 1
        end
        -- print("playerStatus", playerStatus)
    end
    self.Movie:Play()
    self._loopTimes = 0
    -- self.Movie.player:SetFile
end

function UILoadingPanel:GetLoopTimes()
    return self._loopTimes
end


