function UILoadingPanel:OnLoadingResourceErrorHandler_(eventData)
    if not IS_REVIEW then
        return
    end

    if not self.testLabelTxt then
        ---@type UnityEngine.GameObject
        local testLabelObj = GameObject.Instantiate(self.Tips)
        testLabelObj.name  = 'TestLabel'
        testLabelObj.transform:SetParent(self.Tips.transform.parent, false)
        ---@type UnityEngine.RectTransform
        local testLabelRt = testLabelObj:GetComponent(typeof(CS.UnityEngine.RectTransform))
        testLabelRt.pivot = Vector2(0.5, 0.5)
        testLabelRt.anchorMin = Vector2(0, 0)
        testLabelRt.anchorMax = Vector2(1, 1)
        testLabelRt.anchoredPosition = Vector2(0, 0)
        testLabelRt.sizeDelta = Vector2(-40, -20)
        local XLuaUtils = CS.Engine.Lib.XLuaUtils
        ---@type UnityEngine.UI.Text
        local testLabelTxt = testLabelObj:GetComponent(typeof(CS.UnityEngine.UI.Text))
        testLabelTxt.alignment = CS.UnityEngine.TextAnchor.UpperLeft
        testLabelTxt.color = XLuaUtils.HexToColor("#FF6600")
        testLabelTxt.text  = ''
        testLabelTxt.fontSize = 30
        self.testLabelTxt  = testLabelTxt
        CfUtils.GetOrAddComponent(testLabelTxt.gameObject, CS.UnityEngine.UI.Shadow)
    end
    
    if not self.errorList_ then
        self.errorList_ = {}
    end
    table.insert(self.errorList_, string.fmt('[res_error] %1', tostring(eventData.resPath)))
        
    CfUtils.FillText(self.testLabelTxt, table.concat(self.errorList_, '\n'))
    CfUtils.SetActive(self.testLabelTxt, true)
end


return UILoadingPanel